-- Signed-in sessions behind the JWTs.
-- Tables: Session
-- Generated by server/scripts/export-sql.mjs from the migrated database. Run the files in numeric order on an empty database.

BEGIN;

CREATE TABLE public."Session" (
    sid text NOT NULL,
    data text NOT NULL,
    "userId" text,
    "expiresAt" timestamp(3) without time zone NOT NULL,
    i_ts timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    u_ts timestamp(3) without time zone,
    crte_usr_id text,
    updte_usr_id text,
    a_in smallint DEFAULT 1 NOT NULL,
    d_ts timestamp(3) without time zone,
    CONSTRAINT "Session_a_in_check" CHECK ((a_in = ANY (ARRAY[0, 1])))
);

ALTER TABLE ONLY public."Session"
    ADD CONSTRAINT "Session_pkey" PRIMARY KEY (sid);

CREATE INDEX "Session_expiresAt_idx" ON public."Session" USING btree ("expiresAt");

CREATE INDEX "Session_userId_idx" ON public."Session" USING btree ("userId");

CREATE TRIGGER "Session_audit_timestamps" BEFORE UPDATE ON public."Session" FOR EACH ROW EXECUTE FUNCTION public.campus_set_audit_timestamps();

COMMIT;
